const ALPHABET = '123456789ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz';
const ALPHABET_BYTES = [];
for (let i = 0; i < ALPHABET.length; i++) ALPHABET_BYTES.push(ALPHABET.charCodeAt(i));

const INDEXES = new Map();
for (let i = 0; i < ALPHABET.length; i++) INDEXES.set(ALPHABET[i], i);

// bytes: array of integers 0..255 -> base58 string (Python base58.b58encode semantics)
export function b58encodeBytes(bytes) {
  let zeros = 0;
  while (zeros < bytes.length && bytes[zeros] === 0) zeros++;

  // base58 digits, most significant first
  const digits = [];
  for (let i = zeros; i < bytes.length; i++) {
    let carry = bytes[i];
    let j = digits.length - 1;
    while (carry !== 0 || j >= 0) {
      if (j < 0) {
        digits.unshift(0);
        j = 0;
      }
      const acc = digits[j] * 256 + carry;
      digits[j] = acc % 58;
      carry = Math.floor(acc / 58);
      j--;
    }
  }

  let out = '1'.repeat(zeros);
  for (const d of digits) out += ALPHABET[d];
  return out;
}

// text: base58 string -> array of integers 0..255 (Python base58.b58decode semantics)
export function b58decodeText(text) {
  let zeros = 0;
  while (zeros < text.length && text[zeros] === '1') zeros++;

  const bytes = [];
  for (let i = zeros; i < text.length; i++) {
    const ch = text[i];
    if (!INDEXES.has(ch)) {
      throw new Error(`Invalid character ${JSON.stringify(ch)}`);
    }
    let carry = INDEXES.get(ch);
    let j = bytes.length - 1;
    while (carry !== 0 || j >= 0) {
      if (j < 0) {
        bytes.unshift(0);
        j = 0;
      }
      const acc = bytes[j] * 58 + carry;
      bytes[j] = acc % 256;
      carry = Math.floor(acc / 256);
      j--;
    }
  }

  const out = new Array(zeros).fill(0);
  for (const b of bytes) out.push(b);
  return out;
}

// number: non-negative integer (Number or BigInt) -> base58 string
// Python base58.b58encode_int: 0 encodes to b'', no artificial leading '1'.
export function b58encodeInt(number) {
  let n = BigInt(number);
  if (n < 0n) throw new RangeError('b58encodeInt requires a non-negative integer');
  let out = '';
  while (n > 0n) {
    out = ALPHABET[Number(n % 58n)] + out;
    n = n / 58n;
  }
  return out;
}

// text: base58 string -> integer (Python base58.b58decode_int semantics)
export function b58decodeInt(text) {
  let n = 0n;
  for (const ch of text) {
    if (!INDEXES.has(ch)) {
      throw new Error(`Invalid character ${JSON.stringify(ch)}`);
    }
    n = n * 58n + BigInt(INDEXES.get(ch));
  }
  return Number(n);
}

