import { stringToUtf8Bytes } from './lib/utf8.mjs';
import { pythonBytesRepr } from './lib/python_bytes.mjs';
import { b58encodeBytes, b58decodeText, b58encodeInt, b58decodeInt } from './lib/base58_core.mjs';
import { b58encodeCheck, b58decodeCheck } from './lib/base58_check.mjs';
import { parseArgs } from './lib/cli_args.mjs';

const args = parseArgs(process.argv.slice(2));
const a = args.a;
const b = args.b;
const c = args.c;
const d = args.d;
const e = args.e;
const f = args.f;

// Base58 strings are rendered like Python's bytes objects, so wrap the
// ASCII base58 text back into UTF-8 bytes before repr.
const encoded_a = b58encodeBytes(stringToUtf8Bytes(a));
console.log(pythonBytesRepr(stringToUtf8Bytes(encoded_a)));

const decoded_b = b58decodeText(b);
console.log(pythonBytesRepr(decoded_b));

const encoded_check_c = b58encodeCheck(stringToUtf8Bytes(c));
console.log(pythonBytesRepr(stringToUtf8Bytes(encoded_check_c)));

const decoded_check_c = b58decodeCheck(encoded_check_c);
console.log(pythonBytesRepr(decoded_check_c));

const encoded_d = b58encodeBytes(stringToUtf8Bytes(d));
console.log(pythonBytesRepr(stringToUtf8Bytes(encoded_d)));

const decoded_d = b58decodeText(encoded_d);
console.log(pythonBytesRepr(decoded_d));

const encoded_int_e = b58encodeInt(e);
console.log(pythonBytesRepr(stringToUtf8Bytes(encoded_int_e)));

const encoded_int_f = b58encodeInt(f);
console.log(pythonBytesRepr(stringToUtf8Bytes(encoded_int_f)));

const decoded_int_e = b58decodeInt(encoded_int_e);
console.log(decoded_int_e);

const encoded_check_decoded = b58encodeCheck(decoded_b);
console.log(pythonBytesRepr(stringToUtf8Bytes(encoded_check_decoded)));

