args.command:
node --input-type=module -e "
import { b58encodeBytes, b58decodeText, b58encodeInt, b58decodeInt } from '/output/lib/base58_core.mjs';
const checks = [
  [b58encodeBytes([]), ''],
  [b58encodeBytes([0]), '1'],
  [b58encodeBytes([0,0,97,98,99]), '11ZiCa'],
  [b58encodeBytes([104,101,108,108,111,32,119,111,114,108,100]), 'StV1DL6CwTryKyV'],
  [b58encodeInt(0), ''],
  [b58encodeInt(58), '21'],
  [b58encodeInt(123456789), 'BukQL'],
  [String(b58decodeInt('BukQL')), '123456789'],
  [String(b58decodeInt('')), '0'],
  [JSON.stringify(b58decodeText('11ZiCa')), JSON.stringify([0,0,97,98,99])],
];
let ok = true;
for (const [got, want] of checks) { if (got !== want) { ok = false; console.log('MISMATCH', got, want); } }
try { b58decodeText('0'); console.log('MISMATCH: no throw on 0'); ok = false; } catch (e) { if (!(e instanceof Error)) ok = false; }
try { b58decodeInt('OIl'); console.log('MISMATCH: no throw on OIl'); ok = false; } catch (e) {}
// round-trip random data
const rnd = []; for (let i = 0; i < 200; i++) rnd.push(Math.floor(Math.random()*256));
if (JSON.stringify(b58decodeText(b58encodeBytes(rnd))) !== JSON.stringify(rnd)) { ok = false; console.log('MISMATCH roundtrip'); }
console.log(ok ? 'ALL OK' : 'FAILED');
"

