// Manual UTF-8 codec. Byte data is represented as ordinary arrays of
// integers 0..255. No Buffer, no Uint8Array, no imports.

// Encode a JS string (UTF-16) to UTF-8 bytes.
// Valid surrogate pairs are combined into one code point (non-BMP support).
// Lone surrogates are encoded as-is in 3-byte form (like Python's
// surrogatepass / classic JS behavior); ordinary CLI strings never hit this.
export function stringToUtf8Bytes(value) {
  const s = String(value);
  const out = [];
  for (let i = 0; i < s.length; i++) {
    let cp = s.charCodeAt(i);
    if (cp >= 0xd800 && cp <= 0xdbff && i + 1 < s.length) {
      const lo = s.charCodeAt(i + 1);
      if (lo >= 0xdc00 && lo <= 0xdfff) {
        cp = 0x10000 + ((cp - 0xd800) << 10) + (lo - 0xdc00);
        i++;
      }
    }
    if (cp < 0x80) {
      out.push(cp);
    } else if (cp < 0x800) {
      out.push(0xc0 | (cp >> 6), 0x80 | (cp & 0x3f));
    } else if (cp < 0x10000) {
      out.push(
        0xe0 | (cp >> 12),
        0x80 | ((cp >> 6) & 0x3f),
        0x80 | (cp & 0x3f)
      );
    } else {
      out.push(
        0xf0 | (cp >> 18),
        0x80 | ((cp >> 12) & 0x3f),
        0x80 | ((cp >> 6) & 0x3f),
        0x80 | (cp & 0x3f)
      );
    }
  }
  return out;
}

// Decode UTF-8 bytes to a JS string. Strict: throws RangeError on invalid
// UTF-8 (bad continuation bytes, overlong forms, surrogates, > U+10FFFF,
// truncated sequences).
export function bytesToUtf8String(bytes) {
  const n = bytes.length;
  const chunks = [];
  let i = 0;
  const cont = (idx) => {
    if (idx >= n || (bytes[idx] & 0xc0) !== 0x80) {
      throw new RangeError('invalid UTF-8: bad continuation byte');
    }
    return bytes[idx] & 0x3f;
  };
  while (i < n) {
    const b0 = bytes[i];
    let cp, need;
    if (b0 < 0x80) {
      cp = b0;
      need = 0;
    } else if (b0 >= 0xc2 && b0 <= 0xdf) {
      cp = b0 & 0x1f;
      need = 1;
    } else if (b0 >= 0xe0 && b0 <= 0xef) {
      cp = b0 & 0x0f;
      need = 2;
    } else if (b0 >= 0xf0 && b0 <= 0xf4) {
      cp = b0 & 0x07;
      need = 3;
    } else {
      throw new RangeError('invalid UTF-8: bad lead byte');
    }
    for (let k = 1; k <= need; k++) {
      cp = (cp << 6) | cont(i + k);
    }
    i += need + 1;
    if (
      (need === 1 && cp < 0x80) ||
      (need === 2 && cp < 0x800) ||
      (need === 3 && cp < 0x10000)
    ) {
      throw new RangeError('invalid UTF-8: overlong encoding');
    }
    if (cp >= 0xd800 && cp <= 0xdfff) {
      throw new RangeError('invalid UTF-8: surrogate code point');
    }
    if (cp > 0x10ffff) {
      throw new RangeError('invalid UTF-8: code point out of range');
    }
    chunks.push(String.fromCodePoint(cp));
  }
  return chunks.join('');
}

