args.content:
// Render an array of integers 0..255 the way CPython prints a bytes object
// (repr), e.g. b'', b'abc', b'\x00'.
//
// Quote selection matches CPython: use single quotes, unless the data
// contains a single quote but no double quote, in which case use double
// quotes. Escaping: backslash and the active quote are backslash-escaped;
// \t, \n, \r use their short escapes; bytes outside 0x20..0x7e use \xhh
// (lowercase hex).

export function pythonBytesRepr(bytes) {
  let hasSingle = false;
  let hasDouble = false;
  for (const b of bytes) {
    if (b === 0x27) hasSingle = true;
    else if (b === 0x22) hasDouble = true;
  }
  const quote = hasSingle && !hasDouble ? 0x22 : 0x27;

  let out = 'b' + String.fromCharCode(quote);
  for (const b of bytes) {
    if (b === quote || b === 0x5c) {
      out += '\\' + String.fromCharCode(b);
    } else if (b === 0x09) {
      out += '\\t';
    } else if (b === 0x0a) {
      out += '\\n';
    } else if (b === 0x0d) {
      out += '\\r';
    } else if (b >= 0x20 && b < 0x7f) {
      out += String.fromCharCode(b);
    } else {
      out += '\\x' + b.toString(16).padStart(2, '0');
    }
  }
  out += String.fromCharCode(quote);
  return out;
}

