// Base58Check encoding/decoding: payload + first 4 bytes of double-SHA256.
// Byte data is represented as ordinary arrays of integers 0..255.

import { sha256Bytes } from './sha256.mjs';
import { b58encodeBytes, b58decodeText } from './base58_core.mjs';

function checksumOf(bytes) {
  return sha256Bytes(sha256Bytes(bytes)).slice(0, 4);
}

export function b58encodeCheck(bytes) {
  return b58encodeBytes(bytes.concat(checksumOf(bytes)));
}

export function b58decodeCheck(text) {
  const payload = b58decodeText(text);
  if (payload.length < 4) {
    throw new Error('Invalid checksum');
  }
  const body = payload.slice(0, payload.length - 4);
  const expected = checksumOf(body);
  for (let i = 0; i < 4; i += 1) {
    if (payload[payload.length - 4 + i] !== expected[i]) {
      throw new Error('Invalid checksum');
    }
  }
  return body;
}

