// Minimal argparse-like parser for test19: required --a..--d (str), --e/--f (int).
// No imports. Duplicate options: last occurrence wins. Errors exit with code 2.

const PROG = 'test19.py';
const OPTIONS = [
  { flag: '--a', key: 'a', type: 'str' },
  { flag: '--b', key: 'b', type: 'str' },
  { flag: '--c', key: 'c', type: 'str' },
  { flag: '--d', key: 'd', type: 'str' },
  { flag: '--e', key: 'e', type: 'int' },
  { flag: '--f', key: 'f', type: 'int' },
];

function usageLine() {
  const parts = OPTIONS.map((o) => `${o.flag} ${o.flag.slice(2).toUpperCase()}`);
  return `usage: ${PROG} [-h] ${parts.join(' ')}`;
}

function fail(message) {
  process.stderr.write(`${usageLine()}\n`);
  process.stderr.write(`${PROG}: error: ${message}\n`);
  process.exit(2);
}

// Python int() decimal syntax: optional surrounding whitespace, optional sign,
// digits with optional single underscores between digits.
function parsePythonInt(text, flag) {
  const trimmed = text.trim();
  if (!/^[+-]?\d(_?\d)*$/.test(trimmed)) {
    fail(`argument ${flag}: invalid int value: '${text}'`);
  }
  const value = Number(trimmed.replace(/_/g, ''));
  if (!Number.isSafeInteger(value)) {
    fail(`argument ${flag}: invalid int value: '${text}'`);
  }
  return value;
}

export function parseArgs(argv) {
  const values = {};
  const byFlag = new Map(OPTIONS.map((o) => [o.flag, o]));

  for (let i = 0; i < argv.length; i += 1) {
    const token = argv[i];
    if (token === '-h' || token === '--help') {
      process.stdout.write(`${usageLine()}\n`);
      process.exit(0);
    }
    const eq = token.indexOf('=');
    const flag = eq === -1 ? token : token.slice(0, eq);
    const opt = byFlag.get(flag);
    if (!opt) {
      fail(`unrecognized arguments: ${token}`);
    }
    let raw;
    if (eq !== -1) {
      raw = token.slice(eq + 1);
    } else {
      i += 1;
      if (i >= argv.length) {
        fail(`argument ${flag}: expected one argument`);
      }
      raw = argv[i];
    }
    values[opt.key] = opt.type === 'int' ? parsePythonInt(raw, flag) : raw;
  }

  const missing = OPTIONS.filter((o) => !(o.key in values)).map((o) => o.flag);
  if (missing.length > 0) {
    fail(`the following arguments are required: ${missing.join(', ')}`);
  }
  return values;
}

