14	  const digits = [];
15	  for (let i = zeros; i < bytes.length; i++) {
16	    let carry = bytes[i];
17	    let j = digits.length - 1;
18	    while (carry !== 0 || j >= 0) {
19	      if (j < 0) {
20	        digits.unshift(0);
21	        j = 0;
22	      }
23	      const acc = digits[j] * 256 + carry;
24	      digits[j] = acc % 58;
25	      carry = Math.floor(acc / 58);
26	      j--;
27	    }
28	  }
