2	// No imports. Duplicate options: last occurrence wins. Errors exit with code 2.
3	
4	const PROG = 'test19.py';
5	const OPTIONS = [
6	  { flag: '--a', key: 'a', type: 'str' },
7	  { flag: '--b', key: 'b', type: 'str' },
8	  { flag: '--c', key: 'c', type: 'str' },
9	  { flag: '--d', key: 'd', type: 'str' },
10	  { flag: '--e', key: 'e', type: 'int' },
11	  { flag: '--f', key: 'f', type: 'int' },
12	];
13	
14	function usageLine() {
15	  const parts = OPTIONS.map((o) => `${o.flag} ${o.flag.slice(2).toUpperCase()}`);
16	  return `usage: ${PROG} [-h] ${parts.join(' ')}`;
17	}
18	
19	function fail(message) {
20	  process.stderr.write(`${usageLine()}\n`);
21	  process.stderr.write(`${PROG}: error: ${message}\n`);
22	  process.exit(2);
23	}
24	
25	// Python int() decimal syntax: optional surrounding whitespace, optional sign,
26	// digits with optional single underscores between digits.
27	function parsePythonInt(text, flag) {
28	  const trimmed = text.trim();
29	  if (!/^[+-]?\d(_?\d)*$/.test(trimmed)) {
30	    fail(`argument ${flag}: invalid int value: '${text}'`);
31	  }
32	  const value = Number(trimmed.replace(/_/g, ''));
33	  if (!Number.isSafeInteger(value)) {
34	    fail(`argument ${flag}: invalid int value: '${text}'`);
35	  }
36	  return value;
37	}
38	
39	export function parseArgs(argv) {
40	  const values = {};
41	  const byFlag = new Map(OPTIONS.map((o) => [o.flag, o]));
42	
43	  for (let i = 0; i < argv.length; i += 1) {
44	    const token = argv[i];
45	    if (token === '-h' || token === '--help') {
46	      process.stdout.write(`${usageLine()}\n`);
47	      process.exit(0);
48	    }
49	    const eq = token.indexOf('=');
50	    const flag = eq === -1 ? token : token.slice(0, eq);
51	    const opt = byFlag.get(flag);
52	    if (!opt) {
53	      fail(`unrecognized arguments: ${token}`);
54	    }
55	    let raw;
56	    if (eq !== -1) {
57	      raw = token.slice(eq + 1);
58	    } else {
59	      i += 1;
60	      if (i >= argv.length) {
61	        fail(`argument ${flag}: expected one argument`);
62	      }
63	      raw = argv[i];
64	    }
65	    values[opt.key] = opt.type === 'int' ? parsePythonInt(raw, flag) : raw;
66	  }
67	
68	  const missing = OPTIONS.filter((o) => !(o.key in values)).map((o) => o.flag);
69	  if (missing.length > 0) {
70	    fail(`the following arguments are required: ${missing.join(', ')}`);
71	  }
72	  return values;
73	}

