// Minimal argparse-like parser for test19: required --a..--d (str), --e/--f (int).
// No imports. Duplicate options: last occurrence wins. Errors exit with code 2.
// Mirrors Python argparse: required-missing is reported before unrecognized
// extras, extras are collected and reported together, an option-like token is
// never consumed as a value, negative numbers are values, `--` and everything
// after it are extras, and unambiguous long-option prefixes are accepted.

const PROG = 'test19.py';
const OPTIONS = [
  { flag: '--a', key: 'a', type: 'str' },
  { flag: '--b', key: 'b', type: 'str' },
  { flag: '--c', key: 'c', type: 'str' },
  { flag: '--d', key: 'd', type: 'str' },
  { flag: '--e', key: 'e', type: 'int' },
  { flag: '--f', key: 'f', type: 'int' },
];
const LONG_FLAGS = ['--help', ...OPTIONS.map((o) => o.flag)];
// argparse's _negative_number_matcher: such tokens are values, not options.
const NEGATIVE_NUMBER = /^-\d+$|^-\d*\.\d+$/;

function usageLine() {
  const parts = OPTIONS.map((o) => `${o.flag} ${o.flag.slice(2).toUpperCase()}`);
  return `usage: ${PROG} [-h] ${parts.join(' ')}`;
}

function helpText() {
  const lines = OPTIONS.map((o) => `  ${o.flag} ${o.flag.slice(2).toUpperCase()}`);
  return `${usageLine()}\n\noptions:\n  -h, --help  show this help message and exit\n${lines.join('\n')}\n`;
}

function fail(message) {
  process.stderr.write(`${usageLine()}\n`);
  process.stderr.write(`${PROG}: error: ${message}\n`);
  process.exit(2);
}

// A token that argparse would treat as an option string rather than a value:
// starts with '-', is longer than a bare '-', and is not a negative number.
function looksLikeOption(token) {
  return token.length > 1 && token[0] === '-' && !NEGATIVE_NUMBER.test(token);
}

// Python int() decimal syntax: optional surrounding whitespace, optional sign,
// digits with optional single underscores between digits. Arbitrary size, so
// the result is a BigInt (Python argparse type=int has no range limit).
function parsePythonInt(text, flag) {
  const trimmed = text.trim();
  if (!/^[+-]?\d(_?\d)*$/.test(trimmed)) {
    fail(`argument ${flag}: invalid int value: '${text}'`);
  }
  return BigInt(trimmed.replace(/_/g, ''));
}

export function parseArgs(argv) {
  const values = {};
  const extras = [];
  const byFlag = new Map(OPTIONS.map((o) => [o.flag, o]));
  let seenDashDash = false;

  for (let i = 0; i < argv.length; i += 1) {
    const token = argv[i];
    if (seenDashDash) {
      extras.push(token);
      continue;
    }
    if (token === '--') {
      extras.push(token);
      seenDashDash = true;
      continue;
    }

    const eq = token.indexOf('=');
    const flag = eq === -1 ? token : token.slice(0, eq);

    let opt = byFlag.get(flag);
    let isHelp = flag === '-h' || flag === '--help';
    if (!opt && !isHelp && flag.startsWith('--')) {
      // argparse allow_abbrev: an unambiguous prefix of one long option.
      const matches = LONG_FLAGS.filter((f) => f.startsWith(flag));
      if (matches.length === 1) {
        if (matches[0] === '--help') isHelp = true;
        else opt = byFlag.get(matches[0]);
      }
    }
    if (isHelp) {
      process.stdout.write(helpText());
      process.exit(0);
    }
    if (!opt) {
      extras.push(token);
      continue;
    }

    let raw;
    if (eq !== -1) {
      raw = token.slice(eq + 1);
    } else {
      i += 1;
      if (i >= argv.length || looksLikeOption(argv[i])) {
        fail(`argument ${opt.flag}: expected one argument`);
      }
      raw = argv[i];
    }
    values[opt.key] = opt.type === 'int' ? parsePythonInt(raw, opt.flag) : raw;
  }

  const missing = OPTIONS.filter((o) => !(o.key in values)).map((o) => o.flag);
  if (missing.length > 0) {
    fail(`the following arguments are required: ${missing.join(', ')}`);
  }
  if (extras.length > 0) {
    fail(`unrecognized arguments: ${extras.join(' ')}`);
  }
  return values;
}

